<section class="pr-panel"><div class="pr-panel-head"><h2>Payment history</h2></div><div class="pr-table-wrap"><table class="pr-table"><thead><tr><th>Date / reference</th><th>Payment</th><th class="pr-number">Amount</th><th>Status</th><th>Receipt</th><th>Action</th></tr></thead><tbody>@forelse($payments as $payment)<tr><td>{{ $payment->paid_on }}<small>{{ $payment->reference }}</small>@if($payment->kind === 'advance')<small>Deduct: {{ $payment->recovery_month ? \Carbon\Carbon::parse($payment->recovery_month)->format('F Y') : 'Not scheduled (legacy)' }}</small>@endif</td><td>{{ \App\Services\PayrollService::KINDS[$payment->kind] ?? 'Salary advance' }}@if($payment->kind === 'salary' && $payment->payroll_run_id)<small><a href="/payroll/{{ $payment->payroll_run_id }}/salary-batches/{{ $payment->id }}">Batch PB-{{ str_pad($payment->id,5,'0',STR_PAD_LEFT) }} · employee allocations</a></small>@endif
@if(isset($payment->full_name))<small>{{ $payment->full_name }} · {{ $payment->company_name }}</small>@endif</td><td class="pr-number">{{ $payment->currency }} {{ number_format($payment->amount_cents/100,2) }}@if($payment->kind === 'advance')<small>Recovered: {{ number_format(($payment->recovered_cents ?? 0)/100,2) }}</small>@foreach($payment->recoveries ?? [] as $recovery)<small><a href="/payroll/{{ $recovery->run_id }}/employees/{{ $recovery->payroll_item_id }}">{{ \Carbon\Carbon::parse($recovery->month)->format('M Y') }} · {{ number_format($recovery->amount_cents/100,2) }}</a></small>@endforeach<small>Remaining: {{ number_format(($payment->status === 'reversed' ? 0 : $payment->amount_cents - ($payment->recovered_cents ?? 0))/100,2) }}</small>@endif</td><td>{{ ucfirst($payment->status) }}@if($payment->status === 'reversed')<small>{{ $payment->reversed_on }} · {{ $payment->reversal_reason }}</small>@endif</td><td>@if($payment->receipt_path)<a href="/payroll/payments/{{ $payment->id }}/receipt">Download</a>@else<span class="pr-muted">—</span>@endif</td><td>@if($payment->kind === 'advance' && $payment->status === 'posted' && ($payment->recovered_cents ?? 0) == 0)<details><summary>Deduction month</summary><form method="post" action="/payroll/advances/{{ $payment->id }}/schedule" class="pr-inline-form">@csrf<div class="pr-field"><label for="schedule-{{ $payment->id }}">Payroll month</label><input id="schedule-{{ $payment->id }}" name="recovery_month" type="month" min="{{ substr($payment->paid_on,0,7) }}" value="{{ $payment->recovery_month ? substr($payment->recovery_month,0,7) : '' }}" required></div><button class="pr-btn">Save month</button></form></details>@endif @if($payment->status === 'posted' && in_array(strtolower(auth()->user()->role),['admin','manager']))<details><summary>Reverse</summary><form method="post" action="/payroll/payments/{{ $payment->id }}/reverse" class="pr-inline-form" data-confirm="Reverse this payment? The original record will remain in the audit history.">@csrf<div class="pr-field"><label for="reverse-date-{{ $payment->id }}">Date</label><input id="reverse-date-{{ $payment->id }}" name="date" type="date" value="{{ date('Y-m-d') }}" required></div><div class="pr-field"><label for="reverse-reason-{{ $payment->id }}">Reason</label><input id="reverse-reason-{{ $payment->id }}" name="reason" minlength="5" maxlength="1000" required></div><button class="pr-btn pr-btn-danger">Confirm reversal</button></form></details>@else<span class="pr-muted">—</span>@endif</td></tr>@empty<tr><td colspan="6">No payments recorded yet.</td></tr>@endforelse</tbody></table></div></section>
